        for fw in proj.get('frameworks', []):
            tfm = fw.get('framework', '')
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tfm)
                pkgs[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion', '?'))
        result[name] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        pkg_id, tfm = key
        if bv != av:
            changes.append((proj, pkg_id, tfm, bv, av))
        else:
            unchanged.append((proj, pkg_id, tfm, bv))

print('=== CHANGES ===')
if changes:
